<body>
  <div class="page">
    <header>
      <div class="masthead">
        <p class="brand">Kiln Notes</p>
        <p class="fiction">Fictional product study</p>
      </div>

      <div class="intro">
        <p class="eyebrow">Stoneware · 280 ml</p>
        <h1>Pouring cup</h1>
        <p class="lede">A handleless pouring cup with a small spout.</p>
        <p class="price-line">
          <span class="price">USD 42.00</span>
          <span class="price-note">plus flat USD 6.00 shipping</span>
        </p>
      </div>
    </header>

    <main class="shop-grid">
      <section class="media" aria-labelledby="product-record-title">
        <figure>
          <div class="plate">
            <img
              src="assets/pouring-cup.svg"
              width="600"
              height="420"
              alt="Original schematic of a handleless stoneware pouring cup with a small spout, marked 9 cm wide."
            >
          </div>
          <figcaption>
            <span class="caption-kicker">Image note</span>
            Original schematic illustration of the pouring cup; not a photograph or evidence of glaze texture.
          </figcaption>
        </figure>

        <div class="record" id="record">
          <h2 id="product-record-title">Product record</h2>
          <dl class="spec-list">
            <div>
              <dt>Material</dt>
              <dd>Stoneware</dd>
            </div>
            <div>
              <dt>Capacity</dt>
              <dd>280 ml</dd>
            </div>
            <div>
              <dt>Dimensions</dt>
              <dd>9 cm wide × 8 cm tall</dd>
            </div>
          </dl>
        </div>
      </section>

      <aside class="decision" aria-labelledby="decision-title">
        <h2 id="decision-title">Choose and add</h2>
        <p class="rail-intro">Pick a glaze and a whole quantity. Stock is checked before the simulated add.</p>

        <form id="cart-form" novalidate>
          <fieldset aria-describedby="glaze-note">
            <legend>Glaze</legend>
            <div class="glaze-list">
              <label class="glaze" style="--chip: #c7a77b;">
                <input type="radio" name="glaze" value="Sand" data-stock="4" checked>
                <span class="swatch" aria-hidden="true"></span>
                <span class="glaze-name">Sand</span>
                <span class="stock">4 available</span>
                <span class="tick" aria-hidden="true">✓</span>
              </label>

              <label class="glaze" style="--chip: #61574e;">
                <input type="radio" name="glaze" value="Iron" data-stock="2">
                <span class="swatch" aria-hidden="true"></span>
                <span class="glaze-name">Iron</span>
                <span class="stock">2 available</span>
                <span class="tick" aria-hidden="true">✓</span>
              </label>

              <label class="glaze is-soldout">
                <input type="radio" name="glaze" value="Ash" data-stock="0" disabled>
                <span class="swatch" aria-hidden="true"></span>
                <span class="glaze-name">Ash</span>
                <span class="stock stock--out">Sold out</span>
                <span class="tick" aria-hidden="true">✓</span>
              </label>
            </div>
            <p class="micro" id="glaze-note">Stock is listed per glaze. Color chips are flat color references, not a photograph of fired glaze.</p>
          </fieldset>

          <div class="field">
            <div class="field-head">
              <label class="field-label" for="quantity">Quantity</label>
              <span class="stock-line" id="stock-line">Sand: 4 available</span>
            </div>
            <div class="stepper">
              <button class="step" id="decrease" type="button" aria-label="Decrease quantity">−</button>
              <input
                id="quantity"
                name="quantity"
                type="text"
                inputmode="numeric"
                autocomplete="off"
                spellcheck="false"
                value="1"
                aria-describedby="quantity-help quantity-error stock-notice"
              >
              <button class="step" id="increase" type="button" aria-label="Increase quantity">+</button>
            </div>
            <p class="help" id="quantity-help">Whole numbers 1–4. Sand has 4 available.</p>
            <p class="msg msg-error" id="quantity-error" role="alert"></p>
            <p class="stock-notice" id="stock-notice" role="status" aria-live="polite"></p>
          </div>

          <dl class="totals" aria-label="Simulated cart totals">
            <div class="line">
              <dt>
                Item subtotal
                <span class="basis" id="item-basis">Sand × 1 · USD 42.00 each</span>
              </dt>
              <dd id="item-subtotal">USD 42.00</dd>
            </div>
            <div class="line">
              <dt>Flat shipping</dt>
              <dd>USD 6.00</dd>
            </div>
            <div class="line grand">
              <dt>Total</dt>
              <dd><span id="total">USD 48.00</span></dd>
            </div>
          </dl>

          <button class="add" type="submit" aria-describedby="sim-note">Add to simulated cart</button>

          <div class="feedback">
            <p class="msg msg-success" id="cart-success" role="status" aria-live="polite" aria-atomic="true"></p>
            <p class="msg msg-error" id="cart-failure" role="alert" aria-atomic="true"></p>
          </div>

          <p class="sim-note" id="sim-note"><strong>Simulated cart.</strong> No real order is placed and no payment is taken.</p>
        </form>
      </aside>

      <section class="terms" aria-labelledby="terms-title">
        <h2 id="terms-title">Care and returns</h2>
        <dl class="terms-list">
          <div>
            <dt>Care</dt>
            <dd>Hand-wash; do not use on a stovetop.</dd>
          </div>
          <div>
            <dt>Returns</dt>
            <dd>Unused items may be returned within 14 days; buyer pays return postage.</dd>
          </div>
          <div>
            <dt>Shipping</dt>
            <dd>Flat USD 6 shipping in this fictional checkout; no delivery date is promised.</dd>
          </div>
        </dl>
      </section>
    </main>

    <footer>
      <p>Kiln Notes is a fictional product. This page is a simulated cart interaction: it cannot place a real order or take payment.</p>
    </footer>
  </div>

  <script>
    (function () {
      "use strict";

      var PRICE = 42;
      var SHIPPING = 6;
      var QUANTITY_MAX = 4;

      var form = document.getElementById("cart-form");
      var quantityInput = document.getElementById("quantity");
      var quantityHelp = document.getElementById("quantity-help");
      var quantityError = document.getElementById("quantity-error");
      var stockLine = document.getElementById("stock-line");
      var stockNotice = document.getElementById("stock-notice");
      var itemBasis = document.getElementById("item-basis");
      var itemSubtotal = document.getElementById("item-subtotal");
      var total = document.getElementById("total");
      var cartSuccess = document.getElementById("cart-success");
      var cartFailure = document.getElementById("cart-failure");
      var decreaseButton = document.getElementById("decrease");
      var increaseButton = document.getElementById("increase");
      var glazeInputs = Array.prototype.slice.call(document.querySelectorAll('input[name="glaze"]'));

      var hasSubmitted = false;
      var firstValidAttempt = true;

      function money(amount) {
        return "USD " + amount.toFixed(2);
      }

      function selectedGlaze() {
        return glazeInputs.filter(function (input) {
          return input.checked;
        })[0];
      }

      function selectedName() {
        return selectedGlaze().value;
      }

      function selectedStock() {
        return Number(selectedGlaze().getAttribute("data-stock"));
      }

      function allowedMax() {
        return Math.max(1, Math.min(QUANTITY_MAX, selectedStock()));
      }

      function readQuantity() {
        var raw = quantityInput.value.trim();
        var value = Number(raw);
        var max = allowedMax();
        var valid = raw !== "" && Number.isFinite(value) && Number.isInteger(value) && value >= 1 && value <= max;
        return {
          raw: raw,
          value: value,
          max: max,
          stock: selectedStock(),
          name: selectedName(),
          valid: valid
        };
      }

      function quantityProblem() {
        var state = readQuantity();
        var name = state.name;
        var stock = state.stock;
        var max = state.max;

        if (state.raw === "") {
          return "Enter a quantity. Use a whole number from 1 to " + max + " for " + name + " (" + stock + " available).";
        }
        if (!Number.isFinite(state.value)) {
          return "Enter a whole number, such as 2. " + name + " accepts 1–" + max + " (" + stock + " available).";
        }
        if (!Number.isInteger(state.value)) {
          return "Use a whole number, not a fraction. " + name + " accepts 1–" + max + " (" + stock + " available).";
        }
        if (state.value < 1) {
          return "Enter at least 1. " + name + " accepts 1–" + max + " (" + stock + " available).";
        }
        if (state.value > max) {
          return "Choose " + max + " or fewer for " + name + ". " + stock + " available; the limit is " + QUANTITY_MAX + " per add.";
        }
        return "";
      }

      function setQuantityError(message) {
        quantityError.textContent = message || "";
        if (message) {
          quantityInput.setAttribute("aria-invalid", "true");
        } else {
          quantityInput.removeAttribute("aria-invalid");
        }
      }

      function clearOutcome() {
        cartSuccess.textContent = "";
        cartFailure.textContent = "";
      }

      function clearStockNotice() {
        stockNotice.textContent = "";
      }

      function updateTotals() {
        var state = readQuantity();
        var basis = state.valid ? state.value : "—";
        itemBasis.textContent = state.name + " × " + basis + " · " + money(PRICE) + " each";
        itemSubtotal.textContent = state.valid ? money(PRICE * state.value) : "—";
        total.textContent = state.valid ? money(PRICE * state.value + SHIPPING) : "—";
      }

      function updateSteppers() {
        var state = readQuantity();
        decreaseButton.disabled = state.valid && state.value <= 1;
        increaseButton.disabled = state.valid && state.value >= state.max;
      }

      function updateGuidance() {
        var state = readQuantity();
        quantityHelp.textContent = "Whole numbers 1–" + state.max + ". " + state.name + " has " + state.stock + " available.";
        stockLine.textContent = state.name + ": " + state.stock + " available";
      }

      function refresh() {
        updateGuidance();
        updateTotals();
        updateSteppers();
      }

      function announceClamp(from, to, name) {
        stockNotice.textContent = "Quantity changed from " + from + " to " + to + " to match available " + name + " stock.";
      }

      function showFailure(name, quantity) {
        cartSuccess.textContent = "";
        cartFailure.textContent = "Simulated cart attempt failed. Nothing was added and no payment was taken. Your selection is unchanged: " + name + ", quantity " + quantity + ". Try again.";
      }

      function showSuccess(name, quantity) {
        var subtotal = PRICE * quantity;
        var grandTotal = subtotal + SHIPPING;
        cartFailure.textContent = "";
        cartSuccess.textContent = "Added to the simulated cart: " + name + " glaze, quantity " + quantity + ", total " + money(grandTotal) + " (" + money(subtotal) + " item plus " + money(SHIPPING) + " flat shipping). No real order was placed and no payment was taken.";
      }

      glazeInputs.forEach(function (input) {
        input.addEventListener("change", function () {
          if (!input.checked) {
            return;
          }

          clearOutcome();
          clearStockNotice();

          var stock = Number(input.getAttribute("data-stock"));
          var raw = quantityInput.value.trim();
          var value = Number(raw);

          if (raw !== "" && Number.isFinite(value) && value > stock) {
            quantityInput.value = String(stock);
            announceClamp(raw, stock, input.value);
          }

          refresh();
          if (hasSubmitted) {
            setQuantityError(quantityProblem());
          }
        });
      });

      quantityInput.addEventListener("input", function () {
        clearOutcome();
        clearStockNotice();
        refresh();
        if (hasSubmitted) {
          setQuantityError(quantityProblem());
        }
      });

      function step(delta) {
        var state = readQuantity();
        var base = state.raw !== "" && Number.isInteger(state.value) && state.value >= 1 ? state.value : 1;
        var next = Math.min(state.max, Math.max(1, base + delta));

        if (String(next) !== quantityInput.value) {
          quantityInput.value = String(next);
          clearOutcome();
          clearStockNotice();
          refresh();
          if (hasSubmitted) {
            setQuantityError(quantityProblem());
          }
        }
      }

      decreaseButton.addEventListener("click", function () {
        step(-1);
      });

      increaseButton.addEventListener("click", function () {
        step(1);
      });

      form.addEventListener("submit", function (event) {
        event.preventDefault();
        hasSubmitted = true;

        var problem = quantityProblem();

        if (problem) {
          clearOutcome();
          setQuantityError(problem);
          refresh();
          quantityInput.focus();
          return;
        }

        setQuantityError("");

        var state = readQuantity();

        if (firstValidAttempt) {
          firstValidAttempt = false;
          showFailure(state.name, state.value);
          return;
        }

        showSuccess(state.name, state.value);
      });

      refresh();
    })();
  </script>
</body>
</html>
"}

