  var state = readQuantity();
  var base = state.raw !== "" && Number.isInteger(state.value) && state.value >= 1 ? state.value : 1;
  var next = Math.min(state.max, Math.max(1, base + delta));

  if (String(next) !== quantityInput.value) {
