  }
}

input.newString:
function step(delta) {
  var state = readQuantity();
  var next;

  if (state.valid) {
    next = Math.min(state.max, Math.max(1, state.value + delta));
  } else if (Number.isFinite(state.value) && state.value > state.max) {
    next = state.max;
  } else {
    next = 1;
  }

  if (String(next) !== quantityInput.value) {
    quantityInput.value = String(next);
    clearOutcome();
    clearStockNotice();
    refresh();
    if (hasSubmitted) {
      setQuantityError(quantityProblem());
    }
  }
}

