.glaze {
  position: relative;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto 18px;
  align-items: center;
  gap: 10px;
  min-height: 52px;
  padding: 9px 11px;
  border: 1px solid var(--rule);
  border-radius: 4px;
  background: #fffdf8;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease;
}

.glaze:hover {
  border-color: var(--rule-strong);
  background: #fbf4e7;
}

.glaze input {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  opacity: 0;
}

.glaze:has(input:checked) {
  border-color: var(--ink);
  background: var(--surface-warm);
  box-shadow: inset 0 0 0 1px var(--ink);
}

.glaze:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.glaze.is-soldout {
  border-style: dashed;
  background: #f0ebe2;
  color: #5a4d40;
  cursor: not-allowed;
}

.glaze.is-soldout:hover {
  border-color: var(--rule);
  background: #f0ebe2;
}

.swatch {
  width: 22px;
  height: 22px;
  border: 1px solid rgba(42, 35, 28, 0.55);
  border-radius: 50%;
  background: var(--chip);
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.28);
}

.glaze-name {
  font-weight: 650;
  letter-spacing: 0.005em;
}

